fn effect(uv: vec2f, t: f32) -> vec4f {
  // barrel curvature about the centre
  let c = uv - 0.5;
  let r2 = dot(c, c);
  let q = 0.5 + c * (1.0 + params.curvature * r2);
  var col = textureSampleLevel(input, samp, q, 0.0);
  // scanlines: one dark line per `lines` rows of the layer
  let line = 0.5 + 0.5 * sin(q.y * params.lines * 6.2831853);
  col *= 1.0 - params.strength * line;
  // phosphor triads on the columns
  let px = i32(q.x * rexx.size.x) % 3;
  var triad = vec3f(1.0);
  if (px == 0) { triad = vec3f(1.0, 0.7, 0.7); } else if (px == 1) { triad = vec3f(0.7, 1.0, 0.7); } else { triad = vec3f(0.7, 0.7, 1.0); }
  col = vec4f(col.rgb * triad, col.a);
  // vignette
  col *= 1.0 - smoothstep(0.3, 0.75, length(c));
  // outside the curved frame is black
  let inside = step(0.0, q.x) * step(q.x, 1.0) * step(0.0, q.y) * step(q.y, 1.0);
  return col * inside;
}
